#!/usr/bin/env node
// Generate everything that names a concrete model from models/catalog.json + models/tiers.json:
// the subagents, the claude.ai block, docs/MODELOS.md and the tier table in README.md.
//   node scripts/build.mjs           write the files
//   node scripts/build.mjs --check   exit 1 if any generated file is out of date (CI)
import fs from 'node:fs';
import path from 'node:path';
import { ROOT, loadCatalog, loadTiers, resolveAll } from './lib/catalog.mjs';
import { isMain } from './lib/io.mjs';

const GENERATED = '<!-- GENERATED by scripts/build.mjs from models/catalog.json and models/tiers.json. Do not edit by hand. -->';

const AGENT_BODY = {
  fast: `You are the fast tier of a cost-aware router. Do exactly the task in the brief, nothing more, and stay within the files or material it names.

Reply with the result only, in the user's language, plus at most one line on what you did.

If the task turns out to be ambiguous, risky, or bigger than described, stop and reply only:
ESCALATE: <one-line reason>`,
  standard: `You are the standard tier of a cost-aware router. You get a self-contained brief: goal, allowed files or material, constraints, and an acceptance check.

- Do what the brief specifies. Follow the existing style; no unrelated changes.
- Verify against the acceptance check: run tests or commands when you can.

Reply in the user's language with:
1. What changed (files, one line each) or the deliverable itself.
2. How you verified it.
3. Anything you could not do or that needs a decision.

If the brief is ambiguous or the task is bigger than described, stop and reply only:
ESCALATE: <one-line reason>`,
  deep: `You are the deep tier of a cost-aware router: complex work that is still taking shape. Investigate as needed (read the code or material, find the root cause before proposing a change, read the callers of anything you would change), then return:

1. Decision: the recommended approach in two or three sentences, with the main trade-off.
2. Plan: numbered steps naming exact files, functions or sections, and the changes.
3. Risks: what could break and how to verify it.

Do not edit files unless the brief contains the word IMPLEMENT. Be dense: the lead agent executes your plan.`,
  max: `You are the max tier of a cost-aware router: the hardest problems, or a task a lower tier already failed. The brief may include what was tried and why it failed.

- Start from the failure summary, if any. Do not repeat an approach that failed.
- Verify assumptions by reading code and running commands, not by reasoning alone.

Return: 1. Root cause or decision, with the evidence. 2. Plan or fix, with exact locations. 3. Risks and how to verify.

Do not edit files unless the brief contains the word IMPLEMENT.`,
  frontier: `You are the frontier tier of a cost-aware router and the most expensive one. You get the work that justifies it: long multistep research, an analysis carried through to a finished document, spreadsheet or deck, or a problem two lower tiers could not solve (the brief summarizes their attempts).

- For a decision: the options, the trade-offs, and one recommendation with the reason.
- For a fix: the root cause, the smallest correct change, and the acceptance check run.
- For research or a report: the finished deliverable, with sources.

Reply in the user's language.`,
};

export function renderAgent(tierName, tier, route) {
  const effortText = route.effort ? `${route.effort} effort` : 'default effort';
  const when = tier.manual_only
    ? 'Use only when the user asks for it (!fable) or after two failed attempts at the max tier.'
    : `Use when the router tags a prompt tier=${tierName} or the router skill assigns it.`;
  const front = [
    '---',
    `name: ${tier.agent}`,
    `description: Model-router tier "${tierName}" (${route.model.name}, ${effortText}). ${tier.use_for.en} ${when}`,
    `model: ${route.model.id}`,
    ...(route.effort ? [`effort: ${route.effort}`] : []),
    '---',
  ];
  return `${front.join('\n')}\n${GENERATED}\n\n${AGENT_BODY[tierName]}\n`;
}

const nameOf = (catalog, line) => catalog.models.find((m) => m.id === catalog.current[line])?.name || line;

export function renderWeb(catalog, tiers, routes) {
  const n = (line) => nameOf(catalog, line);
  const rows = tiers.order.map((t) => `| ${tiers.tiers[t].label.es} | ${routes[t].model.name} | ${routes[t].effort || '-'} | \`!${t === 'frontier' ? 'fable' : t === 'standard' ? 'std' : t}\` | ${tiers.tiers[t].use_for.es} |`);
  return `${GENERATED}
# Model router para claude.ai (web, escritorio, móvil y Cowork)

claude.ai no puede cambiar de modelo por sí solo. Con este bloque, Claude te avisa en una línea cuando otro modelo encaja mejor con lo que pides, y tú lo cambias en el selector de modelo.

**Cómo usarlo:** copia el texto entre las dos líneas y pégalo en **Ajustes → Perfil → Preferencias** (o en las instrucciones de un Proyecto). Catálogo del ${catalog.updated_at}: cuando Anthropic publique un modelo nuevo, este archivo se regenera y basta con volver a copiarlo.

---

Selección de modelo: clasifica en silencio cada petición por lo que pido, no por el tamaño de lo que pego.
RÁPIDO (${n('haiku')}): consultas, reescrituras, traducciones, resúmenes, formato, extraer datos de un documento.
ESTÁNDAR (${n('sonnet')}): trabajo normal y bien descrito: correos, documentos, tablas, análisis que sé explicar, código claro.
PROFUNDO (${n('opus')}): trabajo complejo o aún sin definir: decisiones abiertas, estrategia, causas desconocidas, análisis con muchas variables.
FRONTERA (${n('fable')}): investigación larga de varios pasos, o un informe, hoja de cálculo o presentación completos de principio a fin.
Solo si el modelo actual encaja claramente mal (PROFUNDO o FRONTERA en ${n('haiku')} o ${n('sonnet')}; RÁPIDO en ${n('opus')} o ${n('fable')}), empieza la respuesta con una línea: "⚙ Mejor opción: <modelo>". Si te pregunto qué modelo usar, recomiéndalo con este criterio. En cualquier otro caso, no menciones nada de esto.

---

## Guía rápida

| Nivel | Modelo | Esfuerzo | Prefijo en Claude Code | Para qué |
|---|---|---|---|---|
${rows.join('\n')}
`;
}

const money = (v) => (v === undefined || v === null ? '-' : `$${v}`);

export function renderDocs(catalog, tiers, routes) {
  const tierRows = tiers.order.map((t) => `| ${tiers.tiers[t].label.es} (\`${t}\`) | ${routes[t].model.name} | \`${routes[t].model.id}\` | ${routes[t].effort || '-'} | ${tiers.tiers[t].use_for.es} |`);
  const modelRows = catalog.models.map((m) => {
    const p = m.price || {};
    const lc = p.long_context ? ` (>${p.long_context.threshold.toLocaleString('es-ES')} tok: ${money(p.long_context.input)} / ${money(p.long_context.output)})` : '';
    const cur = Object.values(catalog.current).includes(m.id) ? ' **(actual)**' : '';
    return `| ${m.name}${cur}${m.availability === 'limited' ? ' (acceso limitado)' : ''} | \`${m.id}\` | ${money(p.input)} / ${money(p.output)}${lc} | ${money(p.cache_read)} | ${m.default_effort || '-'} | ${(m.efforts || []).join(', ') || 'sin parámetro de esfuerzo'} |`;
  });
  return `${GENERATED}
# Modelos y niveles

Catálogo actualizado el **${catalog.updated_at}** (fuente: ${catalog.source === 'api' ? 'Models API de Anthropic' : 'documentación pública de Anthropic'}). Lo regenera cada semana \`.github/workflows/update-models.yml\`.

## Niveles

| Nivel | Modelo | ID | Esfuerzo | Para qué |
|---|---|---|---|---|
${tierRows.join('\n')}

## Catálogo completo

Precios en USD por millón de tokens (entrada / salida), lectura de caché aparte.

| Modelo | ID | Entrada / salida | Lectura de caché | Esfuerzo por defecto | Esfuerzos admitidos |
|---|---|---|---|---|---|
${modelRows.join('\n')}
`;
}

export function renderReadmeTiers(readme, tiers, routes) {
  const start = '<!-- tiers:start -->';
  const end = '<!-- tiers:end -->';
  const i = readme.indexOf(start);
  const j = readme.indexOf(end);
  if (i < 0 || j < i) return readme;
  const rows = tiers.order.map((t) => `| ${tiers.tiers[t].label.es} | ${routes[t].model.name} | ${routes[t].effort || '-'} | ${tiers.tiers[t].use_for.es} |`);
  const table = ['| Nivel | Modelo | Esfuerzo | Para qué |', '|---|---|---|---|', ...rows].join('\n');
  return `${readme.slice(0, i + start.length)}\n${table}\n${readme.slice(j)}`;
}

export function renderAll(root = ROOT) {
  const catalog = loadCatalog(root);
  const tiers = loadTiers(root);
  if (!catalog || !tiers) throw new Error('models/catalog.json or models/tiers.json is missing or invalid');
  const routes = resolveAll(catalog, tiers);
  const files = {};
  for (const t of tiers.order) files[`agents/${tiers.tiers[t].agent}.md`] = renderAgent(t, tiers.tiers[t], routes[t]);
  files['web/claude-ai.md'] = renderWeb(catalog, tiers, routes);
  files['docs/MODELOS.md'] = renderDocs(catalog, tiers, routes);
  const readmePath = path.join(root, 'README.md');
  if (fs.existsSync(readmePath)) files['README.md'] = renderReadmeTiers(fs.readFileSync(readmePath, 'utf8'), tiers, routes);
  return files;
}

export function outOfDate(files, root = ROOT) {
  return Object.entries(files)
    .filter(([rel, content]) => {
      try {
        return fs.readFileSync(path.join(root, rel), 'utf8') !== content;
      } catch {
        return true;
      }
    })
    .map(([rel]) => rel);
}

if (isMain(import.meta.url)) {
  const files = renderAll();
  const stale = outOfDate(files);
  if (process.argv.includes('--check')) {
    if (stale.length) {
      console.error(`Out of date, run "node scripts/build.mjs": ${stale.join(', ')}`);
      process.exit(1);
    }
    console.log('Generated files are up to date.');
  } else {
    for (const rel of stale) {
      fs.mkdirSync(path.dirname(path.join(ROOT, rel)), { recursive: true });
      fs.writeFileSync(path.join(ROOT, rel), files[rel]);
    }
    console.log(stale.length ? `Wrote ${stale.join(', ')}` : 'Nothing to write.');
  }
}
